head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.noti_seq = '';
scwin.isur_cd = '';
scwin.dep_cd = '';
scwin.acpt_num = '';
scwin.gLastJob = '';

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        scwin.initPage();
        $c.libRoundPanel.PanelToGroupBox(panel_1);
        await scwin.read();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10804.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Reject_onclick
 * @description 「거부」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Reject_onclick = function() {
    try {
        scwin.reject('R');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF10804.btn_Reject_onclick" });
    }
};

/**
 * @method
 * @name btn_Approve_onclick
 * @description 「승인」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Approve_onclick = function() {
    try {
        scwin.reject('A');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF10804.btn_Approve_onclick" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {void}
 * @hidden N
 */
scwin.trs_Save_OnFail = function() {
    try {
        alert_error2(trs_Save);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF10804.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        const msg = $c.stf.getMessageParam("MSG-A001", scwin.gLastJob);
        await $c.win.alert(msg);
        const fr_fn_read = $c.frame.path("../").fn_read;
        await $c.win.closePopup();
        fr_fn_read();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10804.trs_Save_OnSuccess" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name read
 * @description read 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.read = async function() {
    url += "&NOTI_SEQ=" + txb_NOTI_SEQ.getValue();
    url += "&ISUR_CD=" + txb_ISUR_CD.getValue();
    url += "&DEP_CD=" + txb_DEP_CD.getValue();
    url += "&SCREN_ID=" + 'ULDSTF10804.xml';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_MASTER",
        action : "/OnlineNotice.do",
        ref : "",
        target : "dts_MASTER=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name initPage
 * @description init Page 처리
 * @returns {void}
 * @hidden N
 */
scwin.initPage = function() {
    scwin.acpt_num = frame.opener.scwin.acpt_num;
    // alert(acpt_num);
    scwin.noti_seq = frame.opener.txb_NOTI_SEQ.getValue();
    scwin.isur_cd = frame.opener.txb_ISUR_CD.getValue();
    scwin.dep_cd = frame.opener.eval("txb_DEP_CD" + scwin.acpt_num).getValue();
    txb_NOTI_SEQ.setValue(scwin.noti_seq);
    txb_ISUR_CD.setValue(scwin.isur_cd);
    txb_DEP_CD.setValue(scwin.dep_cd);
    txb_NOTI_SEQ.hide();
    txb_ISUR_CD.hide();
    txb_DEP_CD.hide();
    txb_MODE.hide();
};

/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {void}
 * @hidden N
 */
scwin.setCode = function() {
    // dts_MASTER.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=KIFRS_LIST";

};

/**
 * @method
 * @name reject
 * @description reject 처리
 * @param {*} mode mode
 * @returns {void}
 * @hidden N
 */
scwin.reject = function(mode) {
    // mode = 'A' : 반송승인, 'R' : 반송거부
    if (mode === 'A') {
        scwin.gLastJob = "승인";
        txb_MODE.setValue('A');
    } else {
        scwin.gLastJob = "거부";
        txb_MODE.setValue('R');
    }
    const res = window.confirm("[" + scwin.gLastJob + "]하시겠습니까?");
    if (res) {
        let url = "/OnlineNotice.do?method=acptTeamReject" + "&SCREN_ID=" + 'ULDSTF10804.xml' + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
        // alert(dts_MASTER.Text);
        trs_Save.Action = url;
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInputMaster=dts_MASTER)";
        trs_Save.post();
    }
};
